// Parse Perplexity response
let opps;
try {
  const content = $input.first().json.choices[0].message.content;
  // Strip markdown code fences if present
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  opps = JSON.parse(cleaned);
  if (!Array.isArray(opps)) opps = [];
} catch (e) {
  opps = [];
}

return [{
  json: {
    opportunities: opps,
    has_opportunities: opps.length > 0,
    count: opps.length
  }
}];

// Parse Claude scoring response
let scored;
try {
  const text = $input.first().json.content[0].text;
  const cleaned = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  scored = JSON.parse(cleaned);
  if (!Array.isArray(scored)) scored = [];
} catch (e) {
  scored = [];
}

// Filter to 6+ relevance
const relevant = scored.filter(o => o.relevance_score >= 6);

return [{
  json: {
    scored_opportunities: scored,
    high_relevance: relevant,
    high_count: relevant.length,
    total_count: scored.length,
    should_email: relevant.length > 0
  }
}];

const opps = $input.first().json.high_relevance;

const rows = opps.map(o => {
  const setAside = o.set_aside ? `<span style="display:inline-block;padding:2px 8px;border-radius:4px;font-size:11px;font-weight:600;color:#fff;background-color:#16a34a;">${o.set_aside}</span>` : '';
  const score = o.relevance_score;
  const scoreColor = score >= 8 ? '#16a34a' : score >= 6 ? '#eab308' : '#6b7280';
  return `<div style="margin-bottom:16px;padding:16px;border:1px solid #e5e7eb;border-radius:8px;">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
      <span style="font-size:15px;font-weight:700;color:#111827;">${o.title || 'Untitled'}</span>
      <span style="display:inline-block;padding:4px 12px;border-radius:12px;font-size:13px;font-weight:700;color:#fff;background-color:${scoreColor};">${score}/10</span>
    </div>
    <p style="margin:0 0 6px;font-size:13px;color:#6b7280;">${o.agency || ''} ${setAside} ${o.type ? '| ' + o.type : ''}</p>
    <p style="margin:0 0 6px;font-size:14px;color:#374151;">${o.summary || ''}</p>
    <p style="margin:0;font-size:13px;color:#6b7280;">${o.solicitation_number ? 'Sol: ' + o.solicitation_number + ' | ' : ''}${o.response_deadline ? 'Due: ' + o.response_deadline + ' | ' : ''}${o.estimated_value ? 'Est: ' + o.estimated_value : ''}</p>
    <p style="margin:4px 0 0;font-size:12px;color:#0369a1;font-style:italic;">${o.relevance_reason || ''}</p>
    ${o.url ? '<a href="' + o.url + '" style="display:inline-block;margin-top:6px;font-size:13px;color:#0369a1;">View on SAM.gov</a>' : ''}
  </div>`;
}).join('');

const html = `<div style="font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif;max-width:600px;margin:0 auto;background:#fff;">
  <div style="background:#00050f;padding:24px 32px;text-align:center;">
    <h1 style="margin:0;font-size:20px;font-weight:700;color:#00E5FA;">MISSION MEETS TECH</h1>
    <p style="margin:4px 0 0;font-size:13px;color:rgba(255,255,255,0.6);">SAM.gov Daily Brief</p>
  </div>
  <div style="padding:32px;">
    <h2 style="font-size:20px;font-weight:700;color:#111827;margin:0 0 8px;">${opps.length} Relevant Opportunit${opps.length === 1 ? 'y' : 'ies'} Found</h2>
    <p style="font-size:14px;color:#6b7280;margin:0 0 24px;">Scored 6+ out of 10 for relevance to MMT focus areas</p>
    ${rows}
  </div>
  <div style="padding:20px 32px;background:#f9fafb;border-top:1px solid #e5e7eb;text-align:center;">
    <p style="margin:0;font-size:13px;color:#6b7280;"><a href="https://missionmeetstech.com" style="color:#0369a1;text-decoration:none;">Mission Meets Tech</a></p>
    <p style="margin:4px 0 0;font-size:11px;color:#9ca3af;">Automated SAM.gov scan. Do not reply.</p>
  </div>
</div>`;

return [{ json: { email_html: html, count: opps.length } }];
